                defense: [delChar(hero[13], 0, -1), 'fort/battle/button_defend'],
                defensetrue: [delChar('fortbattle', 'defense', 1), 'fort/battle/help02'],
                resistance: [delChar('fortbattle', 'resistance'), 'fort/battle/resistance'],
