                  TWX.QIS.popupMenu.addItem(j, '<img src="' + ItemManager.getByBaseId(qs[j].img).image + '" height="20" width="20"><div style="padding-right:20px;text-overflow:ellipsis;white-space:nowrap;overflow:hidden;">' + NAME + '</div>', NAME);
